//! Shared setup for integration tests.
//!
//! Each test gets a fresh database from `TestDb::new`, cloned from a template
//! loaded with the schema generated by `s/generate-test-schema`.

#![allow(dead_code)]

use std::hash::{DefaultHasher, Hash, Hasher};
use std::ops::Deref;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

use axum::Router;
use axum::body::{Body, Bytes, to_bytes};
use axum::extract::{OriginalUri, State};
use axum::http::{HeaderMap, Method, Request, StatusCode, header};
use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use chrono::NaiveDate;
use deadpool_postgres::{Manager, Pool};
use recipeyak::AppState;
use recipeyak::config::Config;
use serde_json::Value;
use tokio::sync::OnceCell;
use tokio_postgres::types::ToSql;
use tokio_postgres::{Client, NoTls, Row};
use tower::ServiceExt;

const PASSWORD: &str = "pbkdf2_sha256$1$salt$hash";

const SCHEMA: &str = include_str!("../schema/0001_schema.sql");

/// Server to create the per-test databases on.
fn database_url() -> String {
    std::env::var("RECIPEYAK_RS_DATABASE_URL")
        .unwrap_or_else(|_| "postgres://postgres@localhost:5432/postgres".into())
}

async fn connect(config: &tokio_postgres::Config) -> Client {
    let (client, connection) = config.connect(NoTls).await.unwrap();
    tokio::spawn(connection);
    client
}

async fn admin() -> Client {
    connect(&database_url().parse().unwrap()).await
}

/// Name of a database with the schema loaded, created once per schema so
/// each test only pays for a `CREATE DATABASE ... TEMPLATE`.
async fn template() -> &'static str {
    static TEMPLATE: OnceCell<String> = OnceCell::const_new();
    TEMPLATE.get_or_init(create_template).await
}

async fn create_template() -> String {
    let mut hasher = DefaultHasher::new();
    SCHEMA.hash(&mut hasher);
    let name = format!("recipeyak_test_template_{:016x}", hasher.finish());

    let admin = admin().await;
    let exists = admin
        .query_opt("SELECT 1 FROM pg_database WHERE datname = $1", &[&name])
        .await
        .unwrap()
        .is_some();
    if exists {
        return name;
    }

    // Load the schema under a scratch name and rename it into place, so other
    // test binaries never clone a half-loaded template.
    let scratch = format!("{name}_{}", std::process::id());
    // Left behind if an earlier run with the same pid was interrupted.
    admin
        .batch_execute(&format!("DROP DATABASE IF EXISTS {scratch}"))
        .await
        .unwrap();
    admin
        .batch_execute(&format!("CREATE DATABASE {scratch}"))
        .await
        .unwrap();
    let mut config: tokio_postgres::Config = database_url().parse().unwrap();
    config.dbname(&scratch);
    let (client, connection) = config.connect(NoTls).await.unwrap();
    let connection = tokio::spawn(connection);
    client.batch_execute(SCHEMA).await.unwrap();
    drop(client);
    connection.await.unwrap().unwrap();

    let renamed = admin
        .batch_execute(&format!("ALTER DATABASE {scratch} RENAME TO {name}"))
        .await;
    if renamed.is_err() {
        // Another test binary created it first.
        admin
            .batch_execute(&format!("DROP DATABASE {scratch}"))
            .await
            .unwrap();
    }
    name
}

/// A database for a single test, dropped when the test ends.
pub struct TestDb {
    name: String,
    pool: Pool,
}

impl TestDb {
    pub async fn new() -> Self {
        static COUNTER: AtomicUsize = AtomicUsize::new(0);
        let name = format!(
            "recipeyak_test_{}_{}",
            std::process::id(),
            COUNTER.fetch_add(1, Ordering::Relaxed)
        );
        let template = template().await;
        admin()
            .await
            .batch_execute(&format!("CREATE DATABASE {name} TEMPLATE {template}"))
            .await
            .unwrap();
        let mut config: tokio_postgres::Config = database_url().parse().unwrap();
        config.dbname(&name);
        let pool = Pool::builder(Manager::new(config, NoTls)).build().unwrap();
        Self { name, pool }
    }
}

impl Deref for TestDb {
    type Target = Pool;

    fn deref(&self) -> &Pool {
        &self.pool
    }
}

impl Drop for TestDb {
    fn drop(&mut self) {
        let sql = format!("DROP DATABASE IF EXISTS {} WITH (FORCE)", self.name);
        // Drop can't be async, so run the query on a runtime of its own.
        let result = std::thread::spawn(move || {
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap()
                .block_on(async { admin().await.batch_execute(&sql).await })
        })
        .join();
        if !matches!(result, Ok(Ok(()))) {
            eprintln!("failed to drop test database {}", self.name);
        }
    }
}

pub async fn execute(pool: &Pool, sql: &str, params: &[&(dyn ToSql + Sync)]) {
    let client = pool.get().await.unwrap();
    client.execute(sql, params).await.unwrap();
}

pub async fn query_one(pool: &Pool, sql: &str, params: &[&(dyn ToSql + Sync)]) -> Row {
    let client = pool.get().await.unwrap();
    client.query_one(sql, params).await.unwrap()
}

/// Run an `INSERT ... RETURNING id`.
async fn insert(pool: &Pool, sql: &str, params: &[&(dyn ToSql + Sync)]) -> i32 {
    let client = pool.get().await.unwrap();
    client.query_one(sql, params).await.unwrap().get(0)
}

pub const HOST: &str = "recipeyak.test";

const ABLY_API_KEY: &str = "app.key:secret";

pub struct TestApp {
    router: Router,
    pub ably: FakeAbly,
}

pub struct TestResponse {
    pub status: StatusCode,
    pub body: Vec<u8>,
}

impl TestResponse {
    pub fn json(&self) -> Value {
        serde_json::from_slice(&self.body).unwrap_or_else(|err| {
            panic!(
                "response is not JSON ({err}): {}",
                String::from_utf8_lossy(&self.body)
            )
        })
    }
}

impl TestApp {
    pub fn new(pool: &Pool) -> Self {
        let ably = FakeAbly::start();
        let config = Config {
            database_url: String::new(),
            storage_url: "https://images.test".parse().unwrap(),
            port: 0,
            ably_api_key: Some(ABLY_API_KEY.into()),
            ably_url: ably.url.parse().unwrap(),
        };
        let state = AppState {
            pool: pool.clone(),
            config: Arc::new(config),
            http: reqwest::Client::new(),
        };
        Self {
            router: recipeyak::app(state),
            ably,
        }
    }

    pub async fn get(&self, uri: &str, session_key: Option<&str>) -> TestResponse {
        self.request(Method::GET, uri, session_key, None).await
    }

    pub async fn post(&self, uri: &str, session_key: Option<&str>, body: Value) -> TestResponse {
        self.request(Method::POST, uri, session_key, Some(body))
            .await
    }

    pub async fn patch(&self, uri: &str, session_key: Option<&str>, body: Value) -> TestResponse {
        self.request(Method::PATCH, uri, session_key, Some(body))
            .await
    }

    pub async fn delete(&self, uri: &str, session_key: Option<&str>) -> TestResponse {
        self.request(Method::DELETE, uri, session_key, None).await
    }

    async fn request(
        &self,
        method: Method,
        uri: &str,
        session_key: Option<&str>,
        body: Option<Value>,
    ) -> TestResponse {
        let mut request = Request::builder()
            .method(method)
            .uri(uri)
            .header(header::HOST, HOST);
        if let Some(key) = session_key {
            request = request.header(header::COOKIE, format!("sessionid={key}"));
        }
        let body = match body {
            Some(body) => {
                request = request.header(header::CONTENT_TYPE, "application/json");
                Body::from(body.to_string())
            }
            None => Body::empty(),
        };
        let response = self
            .router
            .clone()
            .oneshot(request.body(body).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap()
            .to_vec();
        TestResponse { status, body }
    }
}

/// A message published to Ably's REST API.
#[derive(Debug, Clone)]
pub struct Published {
    pub path: String,
    pub name: String,
    /// The message's `data`, decoded from its JSON string.
    pub data: Value,
}

/// Records what the app publishes to Ably, rejecting requests that aren't
/// authenticated with `ABLY_API_KEY` like Ably does.
pub struct FakeAbly {
    url: String,
    published: Arc<Mutex<Vec<Published>>>,
}

impl FakeAbly {
    fn start() -> Self {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        let listener = tokio::net::TcpListener::from_std(listener).unwrap();
        let published = Arc::new(Mutex::new(Vec::new()));
        let router = Router::new()
            .fallback(record_publish)
            .with_state(published.clone());
        tokio::spawn(async move { axum::serve(listener, router).await });
        Self { url, published }
    }

    pub fn published(&self) -> Vec<Published> {
        self.published.lock().unwrap().clone()
    }
}

async fn record_publish(
    State(published): State<Arc<Mutex<Vec<Published>>>>,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
    body: Bytes,
) -> StatusCode {
    // Ably uses the API key as basic auth credentials.
    let credentials = headers
        .get(header::AUTHORIZATION)
        .and_then(|h| h.to_str().ok())
        .and_then(|h| h.strip_prefix("Basic "))
        .and_then(|h| STANDARD.decode(h).ok());
    if credentials.as_deref() != Some(ABLY_API_KEY.as_bytes()) {
        return StatusCode::UNAUTHORIZED;
    }
    let message: Value = serde_json::from_slice(&body).unwrap();
    published.lock().unwrap().push(Published {
        path: uri.path().to_string(),
        name: message["name"].as_str().unwrap().to_string(),
        data: serde_json::from_str(message["data"].as_str().unwrap()).unwrap(),
    });
    StatusCode::CREATED
}

pub async fn create_user(pool: &Pool, email: &str) -> i32 {
    insert(
        pool,
        "INSERT INTO core_myuser (password, email, created, last_updated, theme, theme_night, theme_mode)
         VALUES ($1, $2, now(), now(), 'light', 'dark', 'single') RETURNING id",
        &[&PASSWORD, &email],
    )
    .await
}

pub async fn create_team(pool: &Pool, name: &str) -> i32 {
    insert(
        pool,
        "INSERT INTO core_team (name, created, modified) VALUES ($1, now(), now()) RETURNING id",
        &[&name],
    )
    .await
}

pub async fn add_member(pool: &Pool, team_id: i32, user_id: i32) {
    execute(
        pool,
        "INSERT INTO core_membership (team_id, user_id, level, is_active, calendar_sync_enabled, calendar_secret_key, created, modified)
         VALUES ($1, $2, 'admin', true, false, 'secret', now(), now())",
        &[&team_id, &user_id],
    )
    .await;
}

pub async fn create_calendar(pool: &Pool, team_id: i32, name: &str) -> i32 {
    insert(
        pool,
        "INSERT INTO core_calendar (team_id, name, created, modified) VALUES ($1, $2, now(), now()) RETURNING id",
        &[&team_id, &name],
    )
    .await
}

/// Set the user's selected team and pinned calendar.
pub async fn select_calendar(pool: &Pool, user_id: i32, team_id: i32, calendar_id: i32) {
    execute(
        pool,
        "UPDATE core_myuser SET schedule_team_id = $2, pinned_calendar_id = $3 WHERE id = $1",
        &[&user_id, &team_id, &calendar_id],
    )
    .await;
}

/// A user who is a member of a team, with one of its calendars pinned.
pub struct Account {
    pub user_id: i32,
    pub team_id: i32,
    pub calendar_id: i32,
}

pub async fn create_account(pool: &Pool, email: &str) -> Account {
    let user_id = create_user(pool, email).await;
    let team_id = create_team(pool, "Household").await;
    add_member(pool, team_id, user_id).await;
    let calendar_id = create_calendar(pool, team_id, "Dinners").await;
    select_calendar(pool, user_id, team_id, calendar_id).await;
    Account {
        user_id,
        team_id,
        calendar_id,
    }
}

pub async fn create_recipe(pool: &Pool, team_id: i32, name: &str) -> i32 {
    insert(
        pool,
        "INSERT INTO core_recipe (team_id, name, created, modified) VALUES ($1, $2, now(), now()) RETURNING id",
        &[&team_id, &name],
    )
    .await
}

pub async fn schedule_recipe(pool: &Pool, account: &Account, recipe_id: i32, on: NaiveDate) -> i32 {
    insert(
        pool,
        "INSERT INTO core_scheduledrecipe (recipe_id, team_id, calendar_id, created_by_id, \"on\", created, modified)
         VALUES ($1, $2, $3, $4, $5, now(), now()) RETURNING id",
        &[&recipe_id, &account.team_id, &account.calendar_id, &account.user_id, &on],
    )
    .await
}

/// Store a session for the user and return its key for the cookie.
pub async fn login(pool: &Pool, user_id: i32) -> String {
    let session_key = format!("testsession{user_id:021}");
    execute(
        pool,
        "INSERT INTO user_sessions_session (session_key, session_data, expire_date, last_activity, user_id)
         VALUES ($1, '', now() + interval '1 day', now(), $2)",
        &[&session_key, &user_id],
    )
    .await;
    session_key
}

pub async fn set_primary_image(pool: &Pool, recipe_id: i32, key: &str) -> i32 {
    let upload_id: i32 = insert(
        pool,
        "INSERT INTO core_upload (bucket, key, content_type, completed, recipe_id, created, modified)
         VALUES ('test-bucket', $1, 'image/jpeg', true, $2, now(), now()) RETURNING id",
        &[&key, &recipe_id],
    )
    .await;
    execute(
        pool,
        "UPDATE core_recipe SET primary_image_id = $2 WHERE id = $1",
        &[&recipe_id, &upload_id],
    )
    .await;
    upload_id
}
